function init3D(){canvas=$('canvas');try{renderer=new T.WebGLRenderer({canvas,antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.5));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.shadowMap.enabled=true;renderer.shadowMap.autoUpdate=false;renderer.shadowMap.type=T.PCFSoftShadowMap;scene=new T.Scene();scene.background=new T.Color(0xe8ecdf);perspectiveCamera=new T.PerspectiveCamera(42,1,.05,500);parallelCamera=new T.OrthographicCamera(-5,5,5,-5,.05,500);parallelCamera.aspect=1;camera=perspectiveCamera;if(globalThis.GreenShiftPost)post=GreenShiftPost.create(renderer);renderHemi=new T.HemisphereLight(0xeaf2f6,0x89917a,1.1);scene.add(renderHemi);if(R){environmentTarget=R.environment(renderer,scene);R.loadEnvironment(renderer,scene,target=>{if(target){environmentTarget?.dispose();environmentTarget=target;render();}dirty=true;});}const light=new T.DirectionalLight(0xffe8cb,3);renderSun=light;light.position.set(5,10,6);light.castShadow=true;light.shadow.mapSize.set(1024,1024);light.shadow.camera.left=light.shadow.camera.bottom=-25;light.shadow.camera.right=light.shadow.camera.top=25;light.shadow.normalBias=.018;light.shadow.bias=-.0002;light.shadow.radius=3;scene.add(light);const ground=new T.Mesh(new T.PlaneGeometry(100,100),mat(0xe3e8dc));ground.rotation.x=-Math.PI/2;ground.position.y=-.05;ground.receiveShadow=true;scene.add(ground);new ResizeObserver(()=>{if(!dialog.open)return;const r=canvas.parentElement.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();cameraUpdate();}).observe(canvas.parentElement);canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',pointerDown);canvas.addEventListener('pointermove',pointerMove);canvas.addEventListener('pointerup',()=>pointerUp());canvas.addEventListener('pointercancel',()=>pointerUp(true));canvas.addEventListener('lostpointercapture',()=>pointerUp(true));canvas.addEventListener('wheel',e=>{e.preventDefault();if(cameraView!=='walk')zoom(e.deltaY>0?1.07:.93);},{passive:false});canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();$('webgl').hidden=false;});}catch{$('webgl').hidden=false;}}
$('capture').onclick=()=>{if(!renderer){note('3D is unavailable. Download the measured plan instead.');return;}if(measurementRoot)measurementRoot.visible=false;if(selectionRoot)selectionRoot.visible=false;if(guideLine)guideLine.visible=false;drawFrame();canvas.toBlob(blob=>{if(measurementRoot)measurementRoot.visible=true;if(selectionRoot)selectionRoot.visible=true;if(guideLine)guideLine.visible=true;dirty=true;if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='greenshift-assembly.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);});};
dialog.addEventListener('keydown',e=>{e.stopPropagation();if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.target.isContentEditable)return;const k=e.key.toLowerCase(),mod=e.ctrlKey||e.metaKey;if(!mod&&({m:'move',q:'rotate',p:'push',o:'orbit',h:'pan',l:'draw'})[k]){e.preventDefault();dialog.querySelector('[data-ab-tool='+({m:'move',q:'rotate',p:'push',o:'orbit',h:'pan',l:'draw'})[k]+']').click();return;}if(mod&&['a','c','x','v','d','z','y','s'].includes(k)){e.preventDefault();if(k==='s')$('export').click();if(k==='a')$('select-all').click();if(k==='c')copySelection();if(k==='x'){copySelection();$('delete').click();}if(k==='v')paste();if(k==='d'){copySelection();paste();}if(k==='z')undo(e.shiftKey);if(k==='y')undo(true);return;}if(k==='delete'||k==='backspace'){e.preventDefault();$('delete').click();}if(k==='r')$('turn').click();if(k==='escape'){e.preventDefault();drawStart=null;clearGuide();pointerUp(true);tool='select';sync();render();}if(cameraView==='walk'){const map={w:'forward',s:'back',a:'left',d:'right',arrowup:'forward',arrowdown:'back',arrowleft:'left',arrowright:'right'};if(map[k]){e.preventDefault();held.add(map[k]);}}else if(selected.size&&['arrowleft','arrowright','arrowup','arrowdown'].includes(k)){e.preventDefault();nudge({arrowleft:'left',arrowright:'right',arrowup:'forward',arrowdown:'back'}[k]);}});
dialog.addEventListener('keyup',e=>{held.delete(({w:'forward',s:'back',a:'left',d:'right',arrowup:'forward',arrowdown:'back',arrowleft:'left',arrowright:'right'})[e.key.toLowerCase()]);});
dialog.addEventListener('cancel',e=>{e.preventDefault();drawStart=null;clearGuide();pointerUp(true);tool='select';sync();render();note('Tool cancelled. Your concept is unchanged.');});
dialog.addEventListener('close',()=>{held.clear();cancelAnimationFrame(frameId);pointerUp(true);launch.focus();});window.addEventListener('blur',()=>{held.clear();pointerUp(true);});
